    (hH : IsClosed (H : Set (PadicMeasure p X))) (c : ℤ_[p]) {x : PadicMeasure p X}
    (hx : x ∈ H) : c • x ∈ H

theorem mul_mem_of_dirac_mul_mem {H : AddSubgroup (PadicMeasure p ℤ_[p]ˣ)}
    (hH : IsClosed (H : Set (PadicMeasure p ℤ_[p]ˣ))) {ν : PadicMeasure p ℤ_[p]ˣ}
    (hν : ∀ a : ℤ_[p]ˣ, dirac p a * ν ∈ H) (r : PadicMeasure p ℤ_[p]ˣ) :
    r * ν ∈ H

theorem Col_mem_closure_image_of_levelwise {S : Subgroup (NormCompatUnits p)}
    {u : NormCompatUnits p}
    (h : ∀ n, 1 ≤ n → (u.elems n : ℂ_[p]) ∈
      closure ((fun s : NormCompatUnits p => (s.elems n : ℂ_[p])) '' (S : Set (NormCompatUnits p)))) :
    Col p u ∈ closure (Col p '' (S : Set (NormCompatUnits p)))

lemma tendsto_pow_pow_sub_one {ζ : integerRing K} {n : ℕ}
    (hζ : IsPrimitiveRoot ζ (p ^ n)) (c : ℕ) :
    Filter.Tendsto ((ζ ^ c - 1) ^ ·) Filter.atTop (nhds 0)

lemma teichmullerFun_eq_of_sub_mem {x y : ℤ_[p]}
    (h : x - y ∈ Ideal.span {(p : ℤ_[p])}) :
    teichmullerFun p x = teichmullerFun p y

lemma tendsto_pow_atTop_nhds_zero_of_mem_span {w : ℤ_[p]}
    (hw : w ∈ Ideal.span {(p : ℤ_[p])}) :
    Filter.Tendsto (w ^ ·) Filter.atTop (nhds 0)

lemma onePAdicPow_sub_one_mem (y : ℤ_[p]) (hy : y - 1 ∈ Ideal.span {(p : ℤ_[p])})
    (s : ℤ_[p]) :
    onePAdicPow p y hy s - 1 ∈ Ideal.span {(p : ℤ_[p])}

lemma onePAdicPow_sub_one_mem_pow {y : ℤ_[p]}
    (hy : y - 1 ∈ Ideal.span {(p : ℤ_[p])}) {m : ℕ}
    (hym : y - 1 ∈ Ideal.span {((p : ℤ_[p])) ^ m}) (s : ℤ_[p]) :
    onePAdicPow p y hy s - 1 ∈ Ideal.span {((p : ℤ_[p])) ^ m}

lemma mul_sub_one_mem {y z : ℤ_[p]} (hy : y - 1 ∈ Ideal.span {(p : ℤ_[p])})
    (hz : z - 1 ∈ Ideal.span {(p : ℤ_[p])}) :
    y * z - 1 ∈ Ideal.span {(p : ℤ_[p])}

lemma toFieldChar_prod_natCast {D : ℕ}
    {η : DirichletCharacter (integerRing K) D}
    {n : ℕ} {χ : DirichletCharacter (integerRing K) (p ^ n)}
    {θ : DirichletCharacter (integerRing K) (D * p ^ n)}
    (hθ : θ = (DirichletCharacter.changeLevel (Dvd.intro _ rfl) η)
        * (DirichletCharacter.changeLevel (Dvd.intro_left _ rfl) χ)) (j : ℕ) :
    (toFieldChar θ) ((j : ℕ) : ZMod (D * p ^ n))
      = (toFieldChar η) ((j : ℕ) : ZMod D)
        * (toFieldChar χ) ((j : ℕ) : ZMod (p ^ n))

theorem genBernoulli_eq_zero (χ : DirichletCharacter L N) {k : ℕ}
    (h : χ (-1) ≠ (-1 : L) ^ k) (hk : χ ≠ 1 ∨ k ≠ 1) :
    χ.genBernoulli k = 0

lemma DirichletCharacter.toContinuousMapZp_eq_zero
    (χ : DirichletCharacter R (p ^ n)) (hn : 1 ≤ n) {x : ℤ_[p]}
    (hx : ¬IsUnit x) : χ.toContinuousMapZp x = 0

theorem gaussSum_mul_gaussSum_inv {χ : DirichletCharacter R N}
    (hχ : χ.IsPrimitive) {e : AddChar (ZMod N) R} (he : e.IsPrimitive) :
    gaussSum χ e * gaussSum χ⁻¹ e⁻¹ = (N : R)

theorem norm_gaussSum_eq_one {D : ℕ} [NeZero D] {η : DirichletCharacter L D}
    (hη : η.IsPrimitive) (hD : ¬ (p : ℕ) ∣ D) {ζ : L}
    (hζ : IsPrimitiveRoot ζ D) :
    ‖gaussSum η (AddChar.zmodChar D (hζ.pow_eq_one))‖ = 1
